#include <iostream>
using namespace std;

long long pair_count(long long n) {
    if (n < 2) {
        return 0;
    }
    return n * (n - 1) / 2;
}

int halving_steps(long long remaining) {
    int steps = 0;
    while (remaining > 1) {
        remaining /= 2;
        steps++;
    }
    return steps;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    cout << pair_count(n) << '\n';
    cout << halving_steps(n) << '\n';
    return 0;
}

